solution:
class IdempotentConsumer {
  constructor(handler, store = new Map()) {
    this.handler = handler;
    this.store = store; // key -> { state: 'in_progress' } | { state: 'done', result }
  }

  async handle(msg) {
    const key = msg.idempotencyKey ?? msg.id;
    const seen = this.store.get(key);
    if (seen && seen.state === 'done') return { status: 'duplicate', result: seen.result };
    if (seen && seen.state === 'in_progress') return { status: 'in_progress' };

    // Claim the key BEFORE awaiting, so a concurrent duplicate sees it.
    this.store.set(key, { state: 'in_progress' });
    try {
      const result = await this.handler(msg);
      this.store.set(key, { state: 'done', result });
      return { status: 'processed', result };
    } catch (err) {
      this.store.delete(key); // let a redelivery retry
      throw err;
    }
  }
}

tests.code:
let xp = 0;
const c = new IdempotentConsumer(async (m) => { xp += m.body.xp; return { total: xp }; });
const r = await c.handle({ id: 'm1', body: { student: 's42', xp: 10 } });
assertEqual(r, { status: 'processed', result: { total: 10 } });
assertEqual(xp, 10);

let xp = 0, calls = 0;
const c = new IdempotentConsumer(async (m) => { calls++; xp += m.body.xp; return xp; });
const msg = { id: 'm1', body: { xp: 10 } };
await c.handle(msg);
const r2 = await c.handle(msg);
const r3 = await c.handle(msg);
assertEqual(r2, { status: 'duplicate', result: 10 });
assertEqual(r3.status, 'duplicate');
assertEqual(calls, 1);
assertEqual(xp, 10);

let xp = 0;
const c = new IdempotentConsumer(async (m) => { xp += m.body.xp; return xp; });
await c.handle({ id: 'm1', body: { xp: 10 } });
await c.handle({ id: 'm2', body: { xp: 5 } });
assertEqual(xp, 15);

let calls = 0;
const c = new IdempotentConsumer(async () => { calls++; return 'ok'; });
await c.handle({ id: 'm1', idempotencyKey: 'complete:s42:book7', body: {} });
const r = await c.handle({ id: 'm2', idempotencyKey: 'complete:s42:book7', body: {} });
assertEqual(r.status, 'duplicate', 'same business event re-published with a new message id');
assertEqual(calls, 1);

let calls = 0;
const c = new IdempotentConsumer(async () => { calls++; if (calls === 1) throw new Error('db timeout'); return 'saved'; });
let threw = false;
try { await c.handle({ id: 'm1', body: {} }); } catch (e) { threw = e.message === 'db timeout'; }
assert(threw, 'handler error should be rethrown');
const r = await c.handle({ id: 'm1', body: {} });
assertEqual(r, { status: 'processed', result: 'saved' });
assertEqual(calls, 2);

let calls = 0, release;
const gate = new Promise(r => { release = r; });
const c = new IdempotentConsumer(async () => { calls++; await gate; return 'done'; });
const p1 = c.handle({ id: 'm1', body: {} });
const r2 = await c.handle({ id: 'm1', body: {} });
assertEqual(r2, { status: 'in_progress' });
release();
assertEqual(await p1, { status: 'processed', result: 'done' });
assertEqual(calls, 1);

let xp = 0;
const store = new Map();
const handler = async (m) => { xp += m.body.xp; return xp; };
const workerA = new IdempotentConsumer(handler, store);
const workerB = new IdempotentConsumer(handler, store);
await workerA.handle({ id: 'm1', body: { xp: 10 } });
const r = await workerB.handle({ id: 'm1', body: { xp: 10 } });
assertEqual(r.status, 'duplicate');
assertEqual(xp, 10);
